# 仓储工厂函数：体现仓储模式（Repository Pattern）的核心思想
# 业务代码只依赖 TaskStore 抽象接口，不关心底层是 SQLite 还是 PostgreSQL
def create_store(database_url: str, sqlite_path: str):
    # 如果 database_url 以 postgres 前缀开头 → 使用 PostgreSQL 后端
    # 支持两种常见前缀格式：postgres:// 和 postgresql://
    if database_url.startswith(("postgres://", "postgresql://")):
        return PostgresTaskStore(database_url)
    # 否则使用延迟导入（lazy import）加载 SQLite 后端
    # 延迟导入的好处：不需要 PostgreSQL 驱动时不用安装 psycopg
    from .store import TaskStore
    # 返回 SQLite 实现，sqlite_path 是数据库文件路径（默认 evoagent.db）
    return TaskStore(sqlite_path)
